def is_palindrome(s):
    clean = ""
    for ch in s:
        if ch.isalnum():
            clean += ch.lower()
    left, right = 0, len(clean) - 1
    while left < right:
        a, b = clean[left], clean[right]
        if a != b:
            return False
        left += 1
        right -= 1
    return True

print(is_palindrome(s))

